CREATE TABLE IF NOT EXISTS catalog_generations (generation_id TEXT PRIMARY KEY, status TEXT NOT NULL, created_at TEXT NOT NULL, activated_at TEXT, retired_at TEXT, item_count INTEGER NOT NULL DEFAULT 0, manifest_json TEXT NOT NULL DEFAULT '{}', source_generation_id TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS catalog_generation_items (generation_id TEXT NOT NULL, video_id TEXT NOT NULL, public_category_id TEXT NOT NULL, page_number INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, payload_json TEXT NOT NULL, PRIMARY KEY(generation_id,video_id,public_category_id), FOREIGN KEY(generation_id) REFERENCES catalog_generations(generation_id) ON DELETE CASCADE, FOREIGN KEY(video_id) REFERENCES videos(video_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS catalog_generation_page_jobs (generation_id TEXT NOT NULL, category_id TEXT NOT NULL, page_number INTEGER NOT NULL, status TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(generation_id,category_id,page_number));
CREATE TABLE IF NOT EXISTS catalog_config (config_key TEXT PRIMARY KEY, config_value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_generation_items_feed ON catalog_generation_items(generation_id,public_category_id,page_number,position);
CREATE INDEX IF NOT EXISTS idx_category_alias_canonical ON category_aliases(canonical_category_id);
INSERT OR IGNORE INTO catalog_config(config_key,config_value,updated_at) VALUES ('taxonomy_version','youngtube-content-taxonomy-v1','2026-10-22T04:20:00Z'),('active_generation','legacy-kv','2026-10-22T04:20:00Z'),('catalog_mode','shadow','2026-10-22T04:20:00Z');
